/**
 * @name Command injection via os.system or subprocess
 * @description Using os.system or subprocess with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for os.system calls
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    )
    or
    // Check for subprocess calls
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember("call").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name File system access with untrusted input
 * @description File operations with untrusted input can lead to path traversal or symlink attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/file-system-access
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module FileAccessConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    )
    or
    // os.path operations that could be used for file access
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rename", "stat", "chmod", "chown"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // pathlib operations
    exists(API::CallNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    )
  }
}

module FileAccessFlow = TaintTracking::Global<FileAccessConfig>;
import FileAccessFlow::PathGraph

from FileAccessFlow::PathNode source, FileAccessFlow::PathNode sink
where FileAccessFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File system access with untrusted input from $@.", source.getNode(), "user input"

/**
 * @name XML vulnerabilities
 * @description XML parsing with untrusted input can lead to XXE attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/xml-vulnerabilities
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XmlConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // xml.etree.ElementTree parsing
    exists(API::CallNode call |
      call = API::moduleImport("xml.etree.ElementTree").getMember(["parse", "fromstring"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // xml.dom.minidom parsing
    exists(API::CallNode call |
      call = API::moduleImport("xml.dom.minidom").getMember(["parse", "parseString"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // xml.sax parsing
    exists(API::CallNode call |
      call = API::moduleImport("xml.sax").getMember(["parse", "parseString"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // lxml parsing (if used)
    exists(API::CallNode call |
      call = API::moduleImport("lxml.etree").getMember(["parse", "fromstring"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module XmlFlow = TaintTracking::Global<XmlConfig>;
import XmlFlow::PathGraph

from XmlFlow::PathNode source, XmlFlow::PathNode sink
where XmlFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XML parsing with untrusted input from $@.", source.getNode(), "user input"
